from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    k = len(alphabet)
    char_to_idx = {ch: i for i, ch in enumerate(alphabet)}

    trie = [[-1] * k]
    bad = [False]

    for word in banned:
        curr = 0
        for ch in word:
            c = char_to_idx[ch]
            nxt = trie[curr][c]
            if nxt == -1:
                nxt = len(trie)
                trie[curr][c] = nxt
                trie.append([-1] * k)
                bad.append(False)
            curr = nxt
        bad[curr] = True

    fail = [0] * len(trie)
    queue = deque()
    for c in range(k):
        nxt = trie[0][c]
        if nxt != -1:
            fail[nxt] = 0
            queue.append(nxt)
        else:
            trie[0][c] = 0

    while queue:
        u = queue.popleft()
        if bad[fail[u]]:
            bad[u] = True
        for c in range(k):
            v = trie[u][c]
            if v != -1:
                fail[v] = trie[fail[u]][c]
                queue.append(v)
            else:
                trie[u][c] = trie[fail[u]][c]

    good_nodes = [i for i, is_bad in enumerate(bad) if not is_bad]
    m = len(good_nodes)
    idx_map = {node: i for i, node in enumerate(good_nodes)}

    mat = [[0] * m for _ in range(m)]
    for i, u in enumerate(good_nodes):
        for c in range(k):
            v = trie[u][c]
            if not bad[v]:
                mat[i][idx_map[v]] += 1

    def vec_mat_mul(vec: list[int], matrix: list[list[int]]) -> list[int]:
        res = [0] * m
        for i, val in enumerate(vec):
            if val:
                row = matrix[i]
                for j in range(m):
                    res[j] = (res[j] + val * row[j]) % MOD
        return res

    def mat_mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        res = [[0] * m for _ in range(m)]
        for i in range(m):
            row_res = res[i]
            row_a = a[i]
            for p in range(m):
                val = row_a[p]
                if val:
                    row_b = b[p]
                    for j in range(m):
                        row_res[j] = (row_res[j] + val * row_b[j]) % MOD
        return res

    vec = [0] * m
    vec[0] = 1
    while n > 0:
        if n & 1:
            vec = vec_mat_mul(vec, mat)
        n >>= 1
        if n > 0:
            mat = mat_mul(mat, mat)

    return sum(vec) % MOD
